lock.tfType:
object({
    kind = string
    name = optional(string, null)
  })

managed_identities.tfType:
object({
    system_assigned            = optional(bool, false)
    user_assigned_resource_ids = optional(set(string), [])
  })

timeouts.tfType:
object({
    create = optional(string)
    delete = optional(string)
    read   = optional(string)
    update = optional(string)
  })

ad_administrator.tfType:
map(object({
    tenant_id      = string
    object_id      = string
    principal_name = string
    principal_type = string
  }))

virtual_endpoint.tfType:
map(object({
    name              = string
    replica_server_id = string
    type              = string
  }))

firewall_rules.tfType:
map(object({
    name             = string
    end_ip_address   = string
    start_ip_address = string
  }))

authentication.tfType:
object({
    active_directory_auth_enabled = optional(bool)
    password_auth_enabled         = optional(bool)
    tenant_id                     = optional(string)
  })

maintenance_window.tfType:
object({
    day_of_week  = optional(string)
    start_hour   = optional(number)
    start_minute = optional(number)
  })

databases.tfType:
map(object({
    name      = string
    charset   = optional(string)
    collation = optional(string)
    timeouts = optional(object({
      create = optional(string)
      delete = optional(string)
      read   = optional(string)
    }))
  }))
